param([string]$BuildDirectory="$PSScriptRoot\..\target\x86_64-pc-windows-msvc\debug")
if(-not $env:FLOWMUX_TEST_ARTIFACT_ROOT){throw 'Run this verifier through windows/scripts/run-check.ps1 so temporary artifacts are cleaned automatically.'}
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false)
$BuildDirectory=(Resolve-Path $BuildDirectory).Path;$gui=Join-Path $BuildDirectory 'flowmux.exe';$cli=Join-Path $BuildDirectory 'flowmuxctl.exe'
Add-Type -Path (Join-Path $PSScriptRoot 'CliProbe.cs'),(Join-Path $PSScriptRoot 'OptionsFixture.cs'),(Join-Path $PSScriptRoot 'PaneToolsFixture.cs'),(Join-Path $PSScriptRoot 'FindFixture.cs')
Add-Type -ReferencedAssemblies System.Drawing -Path (Join-Path $PSScriptRoot 'ChromeFixture.cs')
$directory=Join-Path $env:FLOWMUX_TEST_ARTIFACT_ROOT ('usage-'+[guid]::NewGuid());[IO.Directory]::CreateDirectory($directory)|Out-Null
$clock=[Diagnostics.Stopwatch]::StartNew();$owned=$null;$pipeName=$null;$hostOut=$null;$hostErr=$null;$failure=$null;$cleanupErrors=@();$cleaning=$false;$checks=@();$savedLocal=$env:LOCALAPPDATA
$diagnostic=[ordered]@{physicalInput=$false;clipboardAccess=$false;accountCollection=$false;checks=@();lastTree=$null}
function Require([bool]$Value,[string]$Message){if(-not $Value){throw $Message}}
function Budget([int]$Maximum=5000){if($cleaning){return [Math]::Min($Maximum,2000)};$left=75000-$clock.ElapsedMilliseconds;Require ($left -gt 0) 'Usage verification exceeded75s';return [int][Math]::Min($Maximum,$left)}
function Request([string[]]$Arguments,[int]$Maximum=5000){
 Require ([bool]$pipeName) 'Explicit owned pipe required';$diagnostic.lastCommand=$Arguments;$p=[CliProbe]::Start($cli,(@('--pipe',$pipeName,'--json')+$Arguments),$directory,$directory);$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync()
 try{Require ($p.WaitForExit((Budget $Maximum))) 'Owned CLI exceeded deadline';Require ($out.Wait(500)-and $err.Wait(500)) 'Owned CLI pipes did not close';Require ($p.ExitCode -eq 0) ('Owned CLI failed: '+[CliProbe]::Output($err));return ([CliProbe]::Output($out)|ConvertFrom-Json)}
 catch{$diagnostic.commandFailure=@{arguments=$Arguments;stdout=[CliProbe]::Output($out);stderr=[CliProbe]::Output($err)};throw}
 finally{if(-not $p.HasExited){$p.Kill();[CliProbe]::WaitAfterKill($p)};$p.Dispose()}
}
function Tree([int]$Maximum=5000){$t=Request @('tree') $Maximum;Require ($t.background_testing -and -not $owned.HasExited) 'Owned hidden host unavailable';Require (-not [CliProbe]::IsWindowVisible([IntPtr][long]$t.window_handle)) 'Owned main unexpectedly visible';[OptionsFixture]::Describe([long]$t.window_handle,$owned.Id)|Out-Null;$diagnostic.lastTree=$t;return $t}
function Await([scriptblock]$Condition){$watch=[Diagnostics.Stopwatch]::StartNew();do{$left=5000-$watch.ElapsedMilliseconds;Require ($left -ge 100) 'Usage condition exceeded5s';$t=Tree ([int]$left);if(& $Condition $t){return $t};Start-Sleep -Milliseconds 20}while($true)}
function Click([long]$Handle){[OptionsFixture]::Click([OptionsFixture]::Parent($Handle,$owned.Id),$Handle,$owned.Id)}
function Stable($Tree){$s=@($Tree.surfaces|Where-Object {$_.id -ceq $original.id});Require ($s.Count -eq 1 -and @($Tree.surfaces).Count -eq 1 -and $s[0].pid -eq $original.pid -and $s[0].session -ceq $original.session -and $s[0].view_handle -eq $original.view_handle -and $s[0].holder.window -eq $original.holder.window -and $s[0].running) 'Usage changed the live terminal PID/session/view/holder';Require ([OptionsFixture]::Describe([long]$Tree.window_handle,$owned.Id).Enabled) 'Usage disabled its owner'}
function Passed([string]$Name){$script:checks+=,$Name;$diagnostic.checks=$checks;Stable (Tree)}
function Panel($Tree){$p=$Tree.usage.panel;Require ($p.open -and $p.window -and -not $p.native_visible) 'Usage popover not logically open and physically hidden';$native=[OptionsFixture]::Describe([long]$p.window,$owned.Id);Require ($native.Owner -eq $Tree.window_handle -and $native.OwnerEnabled -and [Math]::Abs($native.Width-360*$native.Dpi/96) -le 3) 'Usage popup owner/360DIP width differs';Require (@($p.cards).Count -eq 2) 'Expected Claude and Codex native cards';foreach($card in $p.cards){Require ([OptionsFixture]::Text([long]$card.window,$owned.Id) -ceq $card.text) 'Native card caption differs from retained original text'};Header $Tree $p;return $p}
function Header($Tree,$Panel){
 $controls=@([ChromeFixture]::Read([long]$Panel.window,$owned.Id));$header=@();$client=[ChromeFixture]::Size([long]$Panel.window,$owned.Id)
 foreach($key in @('title','toggle','refresh','spinner')){$control=@($controls|Where-Object {$_.Handle -eq [long]$Panel.$key});Require ($control.Count -eq 1) ('Usage header native control missing: '+$key);$header+=,$control[0]}
 Require ($header[0].Text -ceq 'AI Usage' -and $header[1].Text -ceq 'Show bar' -and $header[2].Text -ceq 'Refresh usage' -and $header[3].Text -ceq 'Refreshing usage') 'Usage header lost its native accessible labels'
 Require (($header[1].Style -band 15) -eq 3 -and ($header[1].Style -band 0x1000) -ne 0 -and [OptionsFixture]::Checked([long]$Panel.window,[long]$Panel.toggle,$owned.Id) -eq [bool]$Tree.usage.bar.enabled) 'Show bar lost its native push-checkbox type or checked state'
 $scale=[OptionsFixture]::Describe([long]$Panel.window,$owned.Id).Dpi/96.0;foreach($button in @($header[1],$header[2])){Require ([Math]::Abs($button.Width-28*$scale) -le 2 -and [Math]::Abs($button.Height-28*$scale) -le 2) 'Usage header actions are not compact28DIP icon controls'}
 Require ($header[0].Shown -and $header[1].Shown -and $header[2].Shown -and $header[3].Shown -eq [bool]$Tree.usage.state.refreshing -and $header[2].Enabled -eq (-not $Tree.usage.state.refreshing)) 'Usage spinner visibility or Refresh enabled state differs from the active request'
 foreach($control in $header){Require ($control.X -ge 0 -and $control.Y -ge 0 -and $control.Width -gt 0 -and $control.Height -gt 0 -and $control.X+$control.Width -le $client[0] -and $control.Y+$control.Height -le $client[1] -and $control.Font -ne 0) 'Usage header control escaped the native popup or lost its font'}
 $shown=@($header|Where-Object {$_.Shown});for($i=0;$i -lt $shown.Count-1;$i++){Require ($shown[$i].X+$shown[$i].Width -le $shown[$i+1].X) 'Usage title/toggle/refresh/spinner order overlaps'}
}
function Color([long]$Value){return ('#{0:x2}{1:x2}{2:x2}' -f ($Value-band 255),(($Value-shr 8)-band 255),(($Value-shr 16)-band 255))}
function Paint($Tree,[bool]$Meters=$true){
 $p=Panel $Tree;$path=Join-Path $directory 'usage.bmp';$capture=Request @('chrome-capture',$path);Require ($capture.root_handle -eq $p.window) 'Capture did not target the actual usage popup';$diagnostic.lastCapture=$capture
 foreach($key in @('toggle','refresh','spinner')){
  $glyph=@($capture.controls|Where-Object {$_.handle -eq [long]$p.$key})
  if($key -eq 'spinner' -and -not $Tree.usage.state.refreshing){Require ($glyph.Count -eq 0) 'Idle spinner still appeared in production capture';continue}
  Require ($glyph.Count -eq 1) ('Production capture omitted Usage header glyph: '+$key);$clip=$glyph[0].clip;$pixels=0
  foreach($color in @(@($p.colors.foreground,$p.colors.muted,$p.colors.progress)|Select-Object -Unique)){$pixels+=[ChromeFixture]::ColorCount($path,[int]$clip.x,[int]$clip.y,[int]$clip.width,[int]$clip.height,(Color $color))}
  Require ($pixels -gt 5) ('Production Usage header glyph was blank: '+$key)
 }
 if($Meters){
 $painted=@($capture.controls|Where-Object {$_.handle -eq $p.cards[0].window});Require ($painted.Count -eq 1) 'Production capture omitted Claude ownerdraw';$rect=$painted[0].clip;Require ($rect.width -gt 0 -and $rect.height -gt 0) 'Claude production paint is clipped away'
 Require ([ChromeFixture]::ColorCount($path,[int]$rect.x,[int]$rect.y,[int]$rect.width,[int]$rect.height,(Color $p.colors.progress)) -gt 10) 'Production ownerdraw did not paint the positive usage meter'
 Require ([ChromeFixture]::ColorCount($path,[int]$rect.x,[int]$rect.y,[int]$rect.width,[int]$rect.height,(Color $p.colors.foreground)) -gt 10) 'Production ownerdraw did not paint provider content'
 };Remove-Item -LiteralPath $path -Force
}
function Bar-Paint($Tree,[bool]$Narrow=$false){
 $bar=$Tree.usage.bar;$scale=[OptionsFixture]::Describe([long]$bar.window,$owned.Id).Dpi/96.0;$size=[ChromeFixture]::Size([long]$bar.window,$owned.Id);$meters=@($bar.meters)
