 $native=@([ChromeFixture]::Read([long]$bar.window,$owned.Id)|Where-Object {$_.Handle -eq $bar.control});Require ($native.Count -eq 1 -and $native[0].Font -ne 0 -and $native[0].X -eq 0 -and $native[0].Y -eq 0 -and $native[0].Width -eq $size[0] -and $native[0].Height -eq $size[1]) 'Usage native painter escaped its row'
 $path=Join-Path $directory 'usage-bar.bmp';$capture=Request @('chrome-capture',$path,'--usage-bar');$diagnostic.lastCapture=$capture
 Require ($capture.root_handle -eq $bar.window -and @($capture.controls|Where-Object {$_.handle -eq $bar.control}).Count -eq 1) 'Usage bar capture did not invoke its actual child painter'
 $bitmap=New-Object Drawing.Bitmap($path)
 try{
  $previousRight=0;$trackY=$null;$icons=0
  Require ([ChromeFixture]::ColorCount($path,0,0,$size[0],[int][Math]::Round($scale),(Color $Tree.usage.panel.colors.track)) -eq $size[0]*[int][Math]::Round($scale)) 'Usage row lost its one-DIP top border'
  for($index=0;$index -lt $meters.Count;$index++){
   $meter=$meters[$index];$layout=$bar.geometry.meters[$index];$track=$layout.track;$label=$layout.text;$icon=$null;if($index -eq 0 -or $meters[$index-1].provider -cne $meter.provider){$icon=@($bar.geometry.icons|Where-Object {$_.provider -ceq $meter.provider})[0].rect};$rects=@($track,$label);if($icon){$rects=@($icon)+$rects;$icons++}
   foreach($rect in $rects){Require ($rect.x -ge $previousRight -and $rect.y -ge 0 -and $rect.width -ge 0 -and $rect.height -gt 0 -and $rect.x+$rect.width -le $size[0] -and $rect.y+$rect.height -le $size[1]) 'Usage inline icon/track/label overlaps or escapes row';$previousRight=$rect.x+$rect.width}
   Require ([Math]::Abs($track.height-4*$scale) -le 1 -and $track.width -ge 0 -and $track.width -le [Math]::Round(95*$scale)+1) 'Usage trough height/width differs';if(-not $Narrow){Require ([Math]::Abs($track.width-95*$scale) -le 1) 'Full-width usage trough is not95DIP'}else{Require ($track.width -lt 95*$scale) 'Narrow usage row did not shrink its troughs'}
   if($null -ne $trackY){Require ($track.y -eq $trackY) 'Usage periods are not on one line'};$trackY=$track.y
   Require ($label.x -ge $track.x+$track.width+[Math]::Round(4*$scale)-1 -and $track.y -ge $label.y -and $track.y+$track.height -le $label.y+$label.height -and $meter.display_text -ceq ([string][Math]::Round($meter.percent)+'%('+$meter.label+')')) 'Usage percent label is not inline with its trough'
   $fill=if($meter.provider -ceq 'claude'){'#d97757'}else{'#7a9dff'};$filled=[int][Math]::Round($track.width*[Math]::Min(100,[Math]::Max(0,$meter.percent))/100,[MidpointRounding]::AwayFromZero)
   if($track.width -gt 0){Require ([ChromeFixture]::ColorCount($path,[int]$track.x,[int]$track.y,[int]$track.width,[int]$track.height,$fill) -eq $filled*$track.height) 'Usage provider color or actual percent fill differs'
   Require ([ChromeFixture]::ColorCount($path,[int]$track.x,[int]$track.y,[int]$track.width,[int]$track.height,(Color $Tree.usage.panel.colors.track)) -eq ($track.width-$filled)*$track.height) 'Usage unfilled track pixels differ'}
   if($icon){Require ([Math]::Abs($icon.width-14*$scale) -le 1 -and [Math]::Abs($icon.height-14*$scale) -le 1) 'Usage provider icon size differs';$background=$bitmap.GetPixel([int]$icon.x,[int]($size[1]-1)).ToArgb();$pixels=0;for($y=[int]$icon.y;$y -lt $icon.y+$icon.height;$y++){for($x=[int]$icon.x;$x -lt $icon.x+$icon.width;$x++){if($bitmap.GetPixel($x,$y).ToArgb() -ne $background){$pixels++}}};Require ($pixels -gt 5) 'Usage provider icon was not painted'}
  }
  Require ($icons -eq 2) 'Usage row must paint one icon per provider'
 }finally{$bitmap.Dispose()}
